\i std.sql
create temp table r as select distinct on (player_id) player_id, rating, games_played from player_rating order by player_id, computed_at desc;
\copy (select sc.game_id, sc.team_id, sc.player_id, sc.position, sc.win, sc.mins, sc.outcome, sc.comp::int comp, sc.mvp_points, sc.accuracy, sc.shots_fired, sc.shots_hit_opponent, sc.shots_hit_opponent_3hit, sc.shots_hit_opponent_medic, sc.shots_hit_team, sc.deactivated_opponent, sc.eliminated_opponent, sc.eliminated_opponent_medic, sc.reset_opponent, sc.assists, sc.times_hit, sc.times_reset, sc.times_hit_by_missile, sc.up_frac, sc.lives_left, sc.eliminated::int elim, sc.rapid_fire, sc.shots_hit_opponent_during_rapid, sc.shots_fired_during_rapid, sc.accuracy_during_rapid, sc.sp_earned, sc.score, sc.nukes_canceled, sc.resupplies_received_ammo, sc.resupplies_received_lives, sc.targets_destroyed, sc.missiles_hit_opponent, sc.ammo_boost, sc.life_boost, sc.nukes_detonated, r.rating from sc left join r using (player_id)) to 'sc.csv' csv header
